<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <div class="page">
    <div class="layout">
      <section class="hero" aria-labelledby="support-title">
        <div>
          <p class="eyebrow">Support</p>
          <h1 id="support-title">Contact our support team</h1>
          <p>
            Send us your details and we’ll route your request to the right specialist.
            We’ll only ask for what we need to get back to you quickly.
          </p>
        </div>

        <div class="hero-panel">
          <strong>Typical response window</strong>
          During business hours, messages are usually reviewed within one business day.
        </div>
      </section>

      <main id="main-content" class="form-card">
        <form id="contact-form" novalidate>
          <div class="form-field">
            <label for="fullName">Full name <span class="required" aria-hidden="true">*</span></label>
            <input
              id="fullName"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="fullName-error"
            />
            <p class="field-error" id="fullName-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="emailAddress">Email address <span class="required" aria-hidden="true">*</span></label>
            <input
              id="emailAddress"
              name="emailAddress"
              type="email"
              autocomplete="email"
              required
              aria-describedby="emailAddress-error"
            />
            <p class="field-error" id="emailAddress-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phoneNumber">Phone number</label>
            <input
              id="phoneNumber"
              name="phoneNumber"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phoneNumber-help phoneNumber-error"
            />
            <p class="field-help" id="phoneNumber-help">
              Optional. Enter 7 to 15 digits. Spaces, hyphens, parentheses, and a leading plus sign are allowed.
              Example: +1 (555) 123-4567.
            </p>
            <p class="field-error" id="phoneNumber-error" aria-live="polite"></p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
            <div id="form-status" class="status" role="status" aria-live="polite"></div>
          </div>
        </form>
      </main>
    </div>
  </div>

  <script>
    const form = document.getElementById('contact-form');
    const status = document.getElementById('form-status');
    const fields = {
      fullName: {
        input: document.getElementById('fullName'),
        error: document.getElementById('fullName-error')
      },
      emailAddress: {
        input: document.getElementById('emailAddress'),
        error: document.getElementById('emailAddress-error')
      },
      phoneNumber: {
        input: document.getElementById('phoneNumber'),
        error: document.getElementById('phoneNumber-error')
      }
    };

    const touched = new Set();

    function setError(name, message) {
      const field = fields[name];
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function phoneIsValid(value) {
      const trimmed = value.trim();
      if (!trimmed) {
        return true;
      }

      if (!/^[0-9+\s().-]+$/.test(trimmed)) {
        return false;
      }

      const digits = trimmed.replace(/\D/g, '');
      return digits.length >= 7 && digits.length <= 15;
    }

    function validateField(name) {
      const { input } = fields[name];
      const value = input.value.trim();
      let message = '';

      if (name === 'fullName') {
        if (!value) {
          message = 'Please enter your full name.';
        }
      } else if (name === 'emailAddress') {
        if (!value) {
          message = 'Please enter your email address.';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
          message = 'Please enter a valid email address, like name@example.com.';
        }
      } else if (name === 'phoneNumber') {
        if (value && !phoneIsValid(value)) {
          message = 'Enter a phone number with 7 to 15 digits using the format shown above.';
        }
      }

      setError(name, message);
      return !message;
    }

    function validateAll() {
      return Object.keys(fields).every(validateField);
    }

    Object.keys(fields).forEach((name) => {
      const { input } = fields[name];

      input.addEventListener('blur', () => {
        touched.add(name);
        validateField(name);
      });

      input.addEventListener('input', () => {
        if (touched.has(name) || form.dataset.submitted === 'true') {
          validateField(name);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      form.dataset.submitted = 'true';
      status.textContent = '';
      status.dataset.state = '';

      const isValid = validateAll();

      if (!isValid) {
        const firstInvalid = Object.values(fields).find(({ input }) => input.getAttribute('aria-invalid') === 'true');
        if (firstInvalid) {
          firstInvalid.input.focus();
        }
        status.textContent = 'Please fix the highlighted fields and try again.';
        status.dataset.state = 'error';
        return;
      }

      status.textContent = 'Your contact details are ready to send.';
      status.dataset.state = 'success';
    });
  </script>
</body>
</html>
